/**
 * HTTP routes that proxy app requests to DeepSpace platform services.
 *
 * The app worker remains the security boundary: caller identity is derived
 * from a verified JWT, caller-supplied identity headers are removed, and app
 * identity is re-asserted only from worker bindings.
 */

import type { Hono } from 'hono'
import type { ContentfulStatusCode } from 'hono/utils/http-status'
import {
  apiWorkerFetch,
  authWorkerFetch,
  BROWSER_PROXY_ROUTES,
  integrationPath,
  isPlatformReservedPath,
  lookupOwn,
  platformWorkerFetch,
  resolveAppRole,
  resolveSessionReadAuth,
  SESSION_COOKIE,
  verifyAgentToken,
  verifyJwt,
  nativeAuthCallback,
  nativeAuthExchange,
  nativeAuthMe,
  nativeAuthSignOut,
  nativeAuthStart,
  nativeAuthToken,
} from 'deepspace/worker'
import type { ExpoAuthBridgeOptions, JwtVerifierConfig, VerifyResult } from 'deepspace/worker'
import { integrations } from '../integrations.js'
import { requireBoardMembership, requireBoardWriteAccess, getBoardMembership, recordCall } from '../lib/rbac.js'
import type { AppContext, Env } from '../../worker.js'

function jwtConfig(env: Env): JwtVerifierConfig {
  return { publicKey: env.AUTH_JWT_PUBLIC_KEY, issuer: env.AUTH_JWT_ISSUER }
}

function recordStub(env: Env): DurableObjectStub {
  return env.RECORD_ROOMS.get(env.RECORD_ROOMS.idFromName(`app:${env.DEEPSPACE_APP_ID}`))
}

export async function resolveAuth(req: Request, env: Env): Promise<VerifyResult | null> {
  const header = req.headers.get('Authorization')
  const token = header?.startsWith('Bearer ') ? header.slice(7) : null
  if (!token) return null
  return (await verifyJwt(jwtConfig(env), token)).result
}

/** Agent credentials are valid only at the exact origin receiving the request. */
export async function resolveAgentAuth(req: Request, env: Env): Promise<VerifyResult | null> {
  const header = req.headers.get('Authorization')
  const token = header?.startsWith('Bearer ') ? header.slice(7) : null
  if (!token) return null
  return (await verifyAgentToken(jwtConfig(env), token, new URL(req.url).origin)).result
}

/**
 * Re-assert this app's identity headers on a proxied request, fail-closed.
 * Never forwards caller-supplied identity; attaches ours only when the app
 * has a token (absent pre-first-deploy — see Env.APP_IDENTITY_TOKEN).
 */
function reassertAppIdentity(headers: Headers, env: Env): void {
  headers.delete('x-app-identity-token')
  headers.delete('x-app-id')
  if (!env.APP_IDENTITY_TOKEN) return
  headers.set('x-app-identity-token', env.APP_IDENTITY_TOKEN)
  headers.set('x-app-id', env.DEEPSPACE_APP_ID)
}

/** Register auth, debug, and integration routes in their required order. */
export function registerAuthAndIntegrationRoutes(app: Hono<AppContext>): void {
  const nativeAuthOptions = (env: Env): ExpoAuthBridgeOptions => ({
    allowedRedirectUris: (env.NATIVE_AUTH_REDIRECT_URIS ?? '')
      .split(',')
      .map((value) => value.trim())
      .filter(Boolean),
  })

  // Native routes must precede the Better Auth wildcard below. The exact
  // browser callback handler branches only when the native bridge's validated
  // redirect_uri is present, so a generated worker cannot shadow native OAuth.
  app.get('/api/auth/native-start', (c) => nativeAuthStart(c.req.raw, c.env, nativeAuthOptions(c.env)))
  app.post('/api/auth/native-exchange', (c) => nativeAuthExchange(c.req.raw, c.env))
  app.post('/api/auth/native-token', (c) => nativeAuthToken(c.req.raw, c.env))
  app.get('/api/auth/native-me', (c) => nativeAuthMe(c.req.raw, c.env))
  app.post('/api/auth/native-signout', (c) => nativeAuthSignOut(c.req.raw, c.env))

  // Social OAuth redirect + code exchange.
  app.get('/api/auth/social-redirect', (c) => {
    const provider = c.req.query('provider')
    if (!provider) return c.json({ error: 'Missing provider' }, 400)

    const appOrigin = new URL(c.req.url).origin
    const authOrigin = new URL(c.env.AUTH_WORKER_URL).origin

    return c.redirect(
      `${authOrigin}/login/social?provider=${encodeURIComponent(provider)}&returnTo=${encodeURIComponent(appOrigin)}`,
    )
  })

  app.get('/api/auth/oauth-complete', async (c) => {
    if (c.req.query('redirect_uri')) {
      return nativeAuthCallback(c.req.raw, c.env, nativeAuthOptions(c.env))
    }
    const code = c.req.query('code')
    const appOrigin = new URL(c.req.url).origin
    // Land the signed-in user in the app, not on the static landing. `/` is a
    // static page (no auth/realtime providers), so redirecting there after auth
    // would strand the user; `/home` is the dynamic app boundary.
    const appHome = `${appOrigin}/home`

    if (!code) return c.redirect(appHome)

    const res = await authWorkerFetch(c.env, '/api/auth/exchange-code', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ code }),
    })

    if (!res.ok) return c.redirect(appHome)
    const data = (await res.json()) as { sessionToken?: string }
    if (!data.sessionToken) return c.redirect(appHome)
    const sessionToken = data.sessionToken

    return new Response(null, {
      status: 302,
      headers: {
        Location: appHome,
        'Set-Cookie': `${SESSION_COOKIE}=${encodeURIComponent(sessionToken)}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000`,
      },
    })
  })

  app.all('/api/auth/sign-out', async (c) => {
    try {
      await authWorkerFetch(c.env, '/api/auth/sign-out', {
        method: c.req.method,
        headers: c.req.raw.headers,
        body: c.req.method !== 'GET' && c.req.method !== 'HEAD' ? c.req.raw.body : undefined,
      })
    } catch {
      // Still expire the app-scoped cookie below. A network/auth-worker
      // failure must not leave the browser immediately signed back in.
    }

    return new Response(JSON.stringify({ success: true }), {
      status: 200,
      headers: {
        'Content-Type': 'application/json',
        'Set-Cookie': `${SESSION_COOKIE}=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0`,
      },
    })
  })

  // Auth proxy → auth-worker (same-origin cookies).
  app.all('/api/auth/*', async (c) => {
    const url = new URL(c.req.url)
    const res = await authWorkerFetch(c.env, url.pathname + url.search, {
      method: c.req.method,
      headers: c.req.raw.headers,
      body: c.req.method !== 'GET' && c.req.method !== 'HEAD' ? c.req.raw.body : undefined,
    })
    const headers = new Headers(res.headers)
    const setCookie = headers.get('set-cookie')
    if (setCookie) {
      headers.set('set-cookie', setCookie.replace(/;\s*Domain=[^;]*/gi, ''))
    }
    return new Response(res.body, { status: res.status, headers })
  })

  // Debug proxy → app's RecordRoom DO.
  //
  // Both this proxy and the DO gate on ALLOW_DEBUG_ROUTES === "true". The app
  // proxy also requires the existing owner/admin role before reaching the DO.
  app.all('/api/debug/*', async (c) => {
    if (c.env.ALLOW_DEBUG_ROUTES !== 'true') {
      return c.notFound()
    }
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'unauthorized' }, 401)
    if ((await resolveAppRole(c.env, auth.userId)) !== 'admin') {
      return c.json({ error: 'forbidden' }, 403)
    }
    const stub = c.env.RECORD_ROOMS.get(
      c.env.RECORD_ROOMS.idFromName(`app:${c.env.DEEPSPACE_APP_ID}`),
    )
    // Forward verbatim: the DO dispatches on the original pathname.
    return stub.fetch(c.req.raw)
  })

  // Integrations proxy → api-worker.
  app.get('/api/integrations', async (c) => {
    try {
      const res = await apiWorkerFetch(c.env, '/api/integrations')
      return new Response(res.body, { status: res.status, headers: res.headers })
    } catch {
      return c.json({ error: 'Failed to fetch integration catalog' }, 502)
    }
  })

  // OAuth connection state is always user-billed, so forward the caller JWT.
  app.get('/api/integrations/status', async (c) => {
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'Sign in required' }, 401)
    const token = c.req.header('Authorization')?.slice(7)
    try {
      const res = await apiWorkerFetch(c.env, '/api/integrations/status', {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
      return new Response(res.body, { status: res.status, headers: res.headers })
    } catch {
      return c.json({ error: 'Status proxy failed' }, 502)
    }
  })

  app.delete('/api/integrations/oauth/:provider/disconnect', async (c) => {
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'Sign in required' }, 401)
    const token = c.req.header('Authorization')?.slice(7)
    const provider = c.req.param('provider')
    try {
      const res = await apiWorkerFetch(
        c.env,
        `/api/integrations/oauth/${encodeURIComponent(provider)}/disconnect`,
        {
          method: 'DELETE',
          headers: token ? { Authorization: `Bearer ${token}` } : {},
        },
      )
      return new Response(res.body, { status: res.status, headers: res.headers })
    } catch {
      return c.json({ error: 'Disconnect proxy failed' }, 502)
    }
  })

  app.all('/api/integrations/:name/:endpoint', async (c) => {
    const integrationName = c.req.param('name')
    // Params arrive decoded, so `..%2F..%2Fapi%2Fusers` would otherwise
    // reach another api-worker route with the owner's token. Plain
    // identifiers only, and own keys only for the config.
    const target = integrationPath(integrationName, c.req.param('endpoint'))
    if (!target) return c.json({ error: 'Unknown integration' }, 404)
    const config = lookupOwn(integrations, integrationName)
    const billingMode = config?.billing ?? 'developer'

    // Sign-in is required unless the app opts this integration into anonymous
    // use; developer billing would otherwise let any visitor spend the owner's
    // credits. User billing always needs a caller to bill.
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth && (billingMode === 'user' || !config?.anonymous)) {
      return c.json({ error: 'Sign in required for this integration' }, 401)
    }

    const headers: Record<string, string> = {
      'Content-Type': c.req.header('Content-Type') ?? 'application/json',
    }

    // The api-worker bills the JWT subject: developer mode uses the app owner;
    // user mode forwards the caller. There is no client billing override.
    if (billingMode === 'developer') {
      headers['Authorization'] = `Bearer ${c.env.APP_OWNER_JWT}`
    } else {
      const token = c.req.header('Authorization')?.slice(7)
      if (token) headers['Authorization'] = `Bearer ${token}`
    }

    // Identify this app for per-app integrations. Pre-first-deploy there is no
    // token, so omit both headers and let the api-worker fail closed.
    if (c.env.APP_IDENTITY_TOKEN) {
      headers['x-app-identity-token'] = c.env.APP_IDENTITY_TOKEN
      headers['x-app-id'] = c.env.DEEPSPACE_APP_ID
    }

    const hasBody = c.req.method !== 'GET' && c.req.method !== 'HEAD'
    const body = hasBody ? await c.req.text() : undefined

    try {
      const res = await apiWorkerFetch(c.env, target, {
        method: c.req.method,
        headers,
        body,
      })
      return new Response(res.body, { status: res.status, headers: res.headers })
    } catch {
      return c.json({ error: 'Integration proxy failed' }, 502)
    }
  })
}

/** Register scoped-file and authenticated browser-to-platform proxies. */
export function registerPlatformProxyRoutes(app: Hono<AppContext>): void {
  // Scoped R2 files → platform-worker. The app has no local R2 binding; the
  // platform bucket scopes keys to the verified app and, by default, user.
  app.all('/api/files/*', async (c) => {
    // A same-origin GET/HEAD with no bearer is identified by the app-origin
    // session cookie, so a private file URL renders in <img>/<audio>/<video>.
    // The fallback lives here, not in resolveAuth, which also gates writes.
    const auth =
      (await resolveAuth(c.req.raw, c.env)) ?? (await resolveSessionReadAuth(c.req.raw, c.env))
    const userId = auth?.userId ?? null

    const url = new URL(c.req.url)
    const platformUrl = new URL(c.req.url)
    platformUrl.pathname = url.pathname.replace('/api/files', '/internal/files')

    const headers = new Headers(c.req.raw.headers)
    // platform-worker trusts x-user-id after app HMAC validation. Always remove
    // caller input and derive it from the verified JWT.
    headers.delete('x-user-id')
    reassertAppIdentity(headers, c.env)
    if (userId) headers.set('x-user-id', userId)

    const resp = await platformWorkerFetch(
      c.env,
      new Request(platformUrl.toString(), {
        method: c.req.method,
        headers,
        body: c.req.raw.body,
      }),
    )

    // Rewrite platform URLs in JSON responses to use the app's origin (a HEAD
    // answer has the content-type but no body).
    const contentType = resp.headers.get('content-type') ?? ''
    if (contentType.includes('application/json') && c.req.method !== 'HEAD') {
      const body = (await resp.json()) as Record<string, unknown>
      const rewriteUrl = (value: string) => value.replace(/^https?:\/\/[^/]+/, url.origin)
      if (typeof body.url === 'string') body.url = rewriteUrl(body.url)
      if (Array.isArray(body.files)) {
        for (const file of body.files as Array<Record<string, unknown>>) {
          if (typeof file.url === 'string') file.url = rewriteUrl(file.url)
        }
      }
      return c.json(body, resp.status as ContentfulStatusCode)
    }

    return new Response(resp.body, { status: resp.status, headers: resp.headers })
  })

  // Same-origin browser proxy for authenticated SDK hooks. Keep this an exact
  // (method, path) allowlist: prefix matching would expose deploy/CLI routes.
  app.all('/_deepspace/*', async (c) => {
    const url = new URL(c.req.url)
    const method = c.req.method
    const route = BROWSER_PROXY_ROUTES.find(
      (candidate) => candidate.method === method && candidate.path === url.pathname,
    )
    if (!route) {
      return c.json({ error: 'not_found' }, 404)
    }

    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth?.userId) return c.json({ error: 'unauthorized' }, 401)

    // Always overwrite caller input with this worker's immutable app id.
    const forwardedParams = new URLSearchParams(url.search)
    forwardedParams.set('appId', c.env.DEEPSPACE_APP_ID)
    const queryString = forwardedParams.toString()
    const apiPath =
      url.pathname.replace('/_deepspace/', '/api/') + (queryString ? `?${queryString}` : '')

    const headers = new Headers(c.req.raw.headers)
    headers.delete('x-user-id')
    reassertAppIdentity(headers, c.env)
    headers.set('x-user-id', auth.userId)

    return apiWorkerFetch(c.env, apiPath, {
      method,
      headers,
      body: ['GET', 'HEAD'].includes(method) ? undefined : c.req.raw.body,
    })
  })
}

const matches = (pathname: string, prefixes: readonly string[]): boolean =>
  prefixes.some((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`))

/**
 * An unmatched API call must 404 without consulting the asset layer at all —
 * answering it with a static file, or with HTML a client then parses as JSON,
 * is never right.
 */
const API_PREFIXES = ['/api']

/**
 * The plain SPA shell prerender.ts (app root) writes beside the prerendered
 * pages: the built index.html with #root still empty. Extensionless, so the
 * asset layer's auto-trailing-slash serves `_spa.html` at it.
 */
const SPA_SHELL_PATH = '/_spa'

/**
 * A FILE, not a client route: last segment carries an extension. Wrong in only
 * the cheap direction — a dotted route 404s visibly, where a missing file
 * getting the shell is HTML parsed as JavaScript and a blank page.
 */
function namesAFile(pathname: string): boolean {
  const last = pathname.slice(pathname.lastIndexOf('/') + 1)
  return last.includes('.')
}

export function registerBoardRoutes(app: Hono<AppContext>): void {
  // GET /api/boards — list boards the caller is a member of
  app.get('/api/boards', async (c) => {
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'Unauthorized' }, 401)

    const payload = await recordCall<{ records?: Array<{ data?: { boardId?: string; role?: string } }> }>(
      c.env,
      'records.query',
      { collection: 'memberships', where: { userId: auth.userId }, limit: 100 },
    )
    if (!payload.success || !payload.data?.records) {
      return c.json({ boards: [] })
    }

    const membershipRecords: Array<{ data?: { boardId?: string; role?: string } }> =
      payload.data.records

    // Fetch board topics for each membership so cards can display them.
    // Skip boards that no longer exist (deleted board, stale membership).
    const boardIds = membershipRecords
      .filter((r): r is { data: { boardId: string; role?: string } } => !!r.data?.boardId)
      .map((r) => r.data.boardId)

    const boards = await Promise.all(
      boardIds.map(async (bid: string) => {
        const bjson = await recordCall<{ record?: { data?: { topic?: string } } }>(
          c.env,
          'records.get',
          { collection: 'boards', recordId: bid },
        )
        if (!bjson.success || !bjson.data?.record?.data?.topic) {
          return null
        }
        const role = membershipRecords.find(
          (r) => r.data?.boardId === bid,
        )?.data?.role
        return {
          boardId: bid,
          role: role ?? 'viewer',
          topic: bjson.data.record.data.topic,
        }
      }),
    )

    return c.json({ boards: boards.filter(Boolean) })
  })

  // GET /api/boards/:id — membership-gated read, 404 for non-members (no existence leak)
  app.get('/api/boards/:id', async (c) => {
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'Unauthorized' }, 401)

    const boardId = c.req.param('id')
    const access = await requireBoardMembership(c.env, boardId, auth.userId)
    if (access instanceof Response) return access

    const stub = recordStub(c.env)
    const json = await stub.fetch(
      new Request('https://internal/api/tools/execute', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': c.env.OWNER_USER_ID,
          'X-App-Action': 'true',
        },
        body: JSON.stringify({
          tool: 'records.get',
          params: { collection: 'boards', recordId: boardId },
        }),
      }),
    )
    const payload = (await json.json()) as { success?: boolean; data?: { record?: { data?: unknown } } }
    if (!payload.success || !payload.data?.record) return c.json({ error: 'Not found' }, 404)
    return c.json(payload.data.record.data)
  })

  // GET /api/boards/:id/claims — claims for a board, 404 for non-members
  app.get('/api/boards/:id/claims', async (c) => {
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'Unauthorized' }, 401)

    const boardId = c.req.param('id')
    const access = await requireBoardMembership(c.env, boardId, auth.userId)
    if (access instanceof Response) return access

    const stub = recordStub(c.env)
    const json = await stub.fetch(
      new Request('https://internal/api/tools/execute', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': c.env.OWNER_USER_ID,
          'X-App-Action': 'true',
        },
        body: JSON.stringify({
          tool: 'records.query',
          params: { collection: 'claims', where: { boardId }, limit: 100 },
        }),
      }),
    )
    const payload = (await json.json()) as {
      success?: boolean
      data?: { records?: Array<{ data?: unknown; id?: string }> }
    }
    if (!payload.success) return c.json({ claims: [] })
    return c.json({ claims: (payload.data?.records ?? []).map((r) => ({ id: r.id, ...(r.data ?? {}) })) })
  })

  // GET /api/claims/:id/evidence — evidence for a claim, 404 if not a member of the claim's board
  app.get('/api/claims/:id/evidence', async (c) => {
    const auth = await resolveAuth(c.req.raw, c.env)
    if (!auth) return c.json({ error: 'Unauthorized' }, 401)

    const claimId = c.req.param('id')

    const stub = recordStub(c.env)
    const claimJson = await stub.fetch(
      new Request('https://internal/api/tools/execute', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': c.env.OWNER_USER_ID,
          'X-App-Action': 'true',
        },
        body: JSON.stringify({
          tool: 'records.get',
          params: { collection: 'claims', recordId: claimId },
        }),
      }),
    )
    const claimPayload = (await claimJson.json()) as {
      success?: boolean
      data?: { record?: { data?: { boardId?: string } } }
    }
    if (!claimPayload.success || !claimPayload.data?.record?.data) {
      return c.json({ error: 'Not found' }, 404)
    }

    const boardId = claimPayload.data.record.data.boardId
    if (!boardId) return c.json({ error: 'Not found' }, 404)
    const access = await requireBoardMembership(c.env, boardId, auth.userId)
    if (access instanceof Response) return access

    const evJson = await stub.fetch(
      new Request('https://internal/api/tools/execute', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-User-Id': c.env.OWNER_USER_ID,
          'X-App-Action': 'true',
        },
        body: JSON.stringify({
          tool: 'records.query',
          params: { collection: 'evidence', where: { claimId }, limit: 100 },
        }),
      }),
    )
    const evPayload = (await evJson.json()) as {
      success?: boolean
      data?: { records?: Array<{ data?: unknown; id?: string }> }
    }
    if (!evPayload.success) return c.json({ evidence: [] })
    return c.json({
      evidence: (evPayload.data?.records ?? []).map((r) => ({ id: r.id, ...(r.data ?? {}) })),
    })
  })
}

/**
 * Register the client-route fallback last so it cannot shadow worker routes.
 * Deploys set `not_found_handling: "none"`, so a 404 from the binding is a
 * real miss and this worker makes the call the asset layer cannot.
 */
export function registerStaticRoutes(app: Hono<AppContext>): void {
  // POST/PUT/DELETE to a mistyped or rolled-back API route gets the same JSON
  // 404 a GET does — Hono's default would answer it with plain text, which is
  // precisely the "text parsed as JSON" failure this guard exists to prevent.
  // Every non-API path falls through to the asset handling below.
  app.all('*', async (c, next) => {
    if (matches(new URL(c.req.url).pathname, API_PREFIXES)) {
      return c.json({ error: 'not_found' }, 404)
    }
    await next()
  })

  app.get('*', async (c) => {
    const url = new URL(c.req.url)
    const response = await c.env.ASSETS.fetch(c.req.raw)
    if (response.status !== 404) return response

    if (namesAFile(url.pathname) || isPlatformReservedPath(url.pathname)) {
      return c.json({ error: 'not_found' }, 404)
    }
    // Once the prerender has run, `/` is the landing page, not an empty
    // shell — serving it for /home would paint the landing for a frame and
    // hand crawlers the `/` canonical on every app route. Ask for the plain
    // shell the build writes first; a build without it (plain SPA,
    // `deepspace dev`) misses and falls through to `/` exactly as before.
    url.pathname = SPA_SHELL_PATH
    const shell = await c.env.ASSETS.fetch(new Request(url.toString(), c.req.raw))
    if (shell.status !== 404) return shell
    // `/`, not `/index.html`: auto-trailing-slash redirects the explicit
    // filename, and the browser would follow it off the URL it asked for.
    url.pathname = '/'
    return c.env.ASSETS.fetch(new Request(url.toString(), c.req.raw))
  })
}
