var SLUG_RE = /^[a-z0-9]+(?:[_.-][a-z0-9]+)*$/;
var HUMAN_MESSAGES = {
  owner_connect_not_ready: "This app isn't ready to accept payments yet \u2014 the app owner needs to finish payment setup.",
  invalid_json: "The request body was not valid JSON.",
  invalid_body: "The request body is invalid.",
  invalid_product_id: "Invalid product id.",
  duplicate_product_id: "Duplicate product id.",
  unknown_product: "Unknown product.",
  too_many_products: "Too many products declared.",
  invalid_amount: "Invalid amount.",
  invalid_name: "Invalid product name.",
  invalid_description: "Invalid product description.",
  unsupported_currency: "Unsupported currency.",
  unknown_app: "Unknown app.",
  not_app_owner: "Only the app owner (or a collaborator) can do this.",
  invalid_return_url: "Invalid return URL.",
  invalid_cancel_url: "Invalid cancel URL.",
  unknown_plan: "Unknown subscription plan.",
  unknown_price: "No price is configured for that billing interval.",
  no_subscription: "No subscription found for this account."
};
function normalizeApiError(status, body) {
  const payload = body !== null && typeof body === "object" ? body : {};
  const rawError = typeof payload.error === "string" ? payload.error : void 0;
  const message = typeof payload.message === "string" ? payload.message : void 0;
  const humanError = rawError !== void 0 && !SLUG_RE.test(rawError) ? rawError : void 0;
  const code = rawError !== void 0 && SLUG_RE.test(rawError) ? rawError : typeof payload.code === "string" && SLUG_RE.test(payload.code) ? payload.code : void 0;
  const details = {};
  for (const [key, value] of Object.entries(payload)) {
    if (key === "success" || key === "error" || key === "message" || key === "issues" || key === "code")
      continue;
    details[key] = value;
  }
  return {
    error: message ?? humanError ?? (code !== void 0 ? HUMAN_MESSAGES[code] : void 0) ?? rawError ?? `Request failed (${status})`,
    ...code !== void 0 ? { code } : {},
    status,
    ...Object.keys(details).length > 0 ? { details } : {},
    ...Array.isArray(payload.issues) ? { issues: payload.issues } : {}
  };
}

// src/server/worker-error.ts
function workerErrorHandler(prefix, respond = (c) => c.text("Internal Server Error", 500)) {
  return (err, c) => {
    if ("getResponse" in err) {
      const res = err.getResponse();
      return c.newResponse(res.body, res);
    }
    console.error(
      `[${prefix}] ${c.req.method} ${new URL(c.req.url).pathname}: ${loggableError(err)}`
    );
    return respond(c);
  };
}

